const fs=require("fs"),path=require("path"),postcss=require("postcss"),cssnano=require("cssnano"),terser=require("terser");async function processFiles(){console.log("🚀 Starting minification process...");const s=path.join(process.cwd(),"src/styles");if(fs.existsSync(s)){const e=fs.readdirSync(s).filter(s=>s.endsWith(".css")&&!s.endsWith(".min.css"));for(const i of e){const e=path.join(s,i),o=path.join(s,i.replace(".css",".min.css")),n=fs.readFileSync(e,"utf8");try{const s=await postcss([cssnano]).process(n,{from:e,to:o});fs.writeFileSync(o,s.css),console.log(`✅ Minified CSS: ${i} -> ${path.basename(o)}`)}catch(s){console.error(`❌ Error minifying ${i}:`,s)}}}const e=path.join(process.cwd(),"scripts");if(fs.existsSync(e)){const s=fs.readdirSync(e).filter(s=>s.endsWith(".js")&&!s.endsWith(".min.js"));for(const i of s){const s=path.join(e,i),o=path.join(e,i.replace(".js",".min.js")),n=fs.readFileSync(s,"utf8");try{const s=await terser.minify(n);s.code&&(fs.writeFileSync(o,s.code),console.log(`✅ Minified JS: ${i} -> ${path.basename(o)}`))}catch(s){console.error(`❌ Error minifying ${i}:`,s)}}}console.log("✨ Minification complete!")}processFiles().catch(s=>{console.error("💥 Minification failed:",s),process.exit(1)});